import UIKit

/// The cover photo for each place worth a lifetime: freely licensed pictures from Wikimedia
/// Commons, shipped with the app so they show everywhere, mainland China included. Each is
/// credited on its page as its licence asks.
enum MustSeePhotos {
    struct Credit: Sendable {
        let artist: String
        let license: String
        let page: URL
    }

    static func credit(_ id: String) -> Credit? { credits[id] }

    static func cover(_ id: String) async -> UIImage? { await load("mustsee-\(id)") }
    static func thumb(_ id: String) async -> UIImage? { await load("mustsee-\(id)-s") }

    nonisolated(unsafe) private static let cache = NSCache<NSString, UIImage>()

    /// Decoded off the main thread, so a list of a hundred scrolls smoothly.
    private static func load(_ name: String) async -> UIImage? {
        if let hit = cache.object(forKey: name as NSString) { return hit }
        guard let url = Bundle.main.url(forResource: name, withExtension: "heic") else { return nil }
        let image = await Task.detached(priority: .userInitiated) {
            UIImage(contentsOfFile: url.path)?.preparingForDisplay()
        }.value
        if let image { cache.setObject(image, forKey: name as NSString) }
        return image
    }

